const mathAndCsExamples = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll(".arxiv-result"));
  return items.map(item => {
    const title = item.querySelector(".title")?.textContent?.trim().replace(/\s+/g, ' ').replace(/^Title:\s*/, '');
    const authors = item.querySelector(".authors")?.textContent?.trim().replace(/\s+/g, ' ').replace(/^Authors:\s*/, '');
    const link = item.querySelector(".list-title a");
    const dateText = Array.from(item.querySelectorAll("p.is-size-7")).find(p => p.textContent.includes("Submitted"))?.textContent.trim().replace(/\s+/g, ' ');
    const tags = Array.from(item.querySelectorAll(".tags .tag")).map(t => t.textContent.trim());
    return {
      id: link?.textContent?.trim(),
      url: link?.href,
      title,
      authors,
      date: dateText,
      tags
    };
  });
});

console.log("Current page results count:", mathAndCsExamples.length);
